"""Markdown report. The automatic part is regenerated by `build`; the
synthesis section between the CLAUDE markers is written by Claude and kept
across rebuilds."""
from __future__ import annotations

import collections
import datetime as dt
from pathlib import Path

from .outputs import has_xy, read_csv

START, END = "<!-- CLAUDE-SYNTHESIS-START -->", "<!-- CLAUDE-SYNTHESIS-END -->"
PLACEHOLDER = ("_Not written yet. Claude fills this section after reading the leads, the flora text hits and the "
               "candidate sites (see SKILL.md, step 5)._")


def _md_table(rows, cols, limit=None):
    rows = rows[:limit] if limit else rows
    if not rows:
        return "_none_\n"
    esc = lambda v: str(v if v is not None else "").replace("|", "\\|").replace("\n", " ")[:160]
    out = "| " + " | ".join(cols) + " |\n|" + "---|" * len(cols) + "\n"
    out += "".join("| " + " | ".join(esc(r.get(c)) for c in cols) + " |\n" for r in rows)
    return out


def write_text_hits_md(path: Path, hits: list[dict]) -> None:
    by = collections.defaultdict(list)
    for h in hits:
        by[h["corpus"]].append(h)
    parts = ["# Flora and PDF text hits\n\nEach block: the matched name plus the text that follows it "
             "(locality lists usually come after the description).\n"]
    for corpus, hs in by.items():
        parts.append(f"\n## {corpus}\n\nFile: `{hs[0]['file']}`\n")
        for h in hs:
            parts.append(f"\n### p. {h['page']} — {h['matched']}\n\n```text\n{h['context']}\n```\n")
    path.write_text("".join(parts), encoding="utf-8")


def write_report(d: Path, nm: dict, recs: list[dict], sites: list[dict], n2k: list[dict], areas: list[dict]) -> None:
    rp = d / "report.md"
    synthesis = PLACEHOLDER
    if rp.exists():
        old = rp.read_text(encoding="utf-8")
        if START in old and END in old:
            synthesis = old.split(START, 1)[1].split(END, 1)[0].strip() or PLACEHOLDER
    log = read_csv(d / "sources_log.csv")
    leads = read_csv(d / "leads.csv")
    lit = read_csv(d / "literature_localities.csv")
    prim = [r for r in recs if r.get("is_primary") == "yes"]
    by_src = collections.Counter(r["source"] for r in recs)
    with_xy = collections.Counter(r["source"] for r in recs if has_xy(r))
    gen = collections.Counter(r["source"] for r in recs if r.get("coords_generalised") == "yes")
    src_rows = [{"source": s, "records": n, "with coordinates": with_xy[s], "generalised/withheld": gen[s]}
                for s, n in by_src.most_common()]
    inst = collections.Counter(r.get("institution") or "?" for r in prim if r["source"] != "iNaturalist")
    regions = ", ".join(f"{a['area']} ({a['code']}, {a['status']})" for a in nm.get("greek_distribution", [])) or "—"
    kinds = collections.Counter(l["kind"] or "?" for l in leads)
    thesis = [l for l in leads if any(k in (l["kind"] or "").lower() for k in ("thesis", "εργασία", "διατριβή"))]
    other = [l for l in leads if l not in thesis]
    problems = [r for r in log if r.get("status") not in ("ok",)]
    withheld = [r for r in prim if r.get("coords_generalised") == "yes" and r["source"] == "DiSSCo Hellas"]
    w_inst = collections.Counter(r.get("institution") for r in withheld)

    md = f"""# {nm['accepted_full']} — known localities in Greece

Generated {dt.date.today():%Y-%m-%d} by greek-plant-localities. Query: “{nm['query']}”.

## Names searched

- **Accepted (Flora of Greece):** {nm['accepted_full']}; family {nm.get('family') or '—'}; GBIF taxonKey {nm.get('gbif_taxon_key') or '—'}
- **Synonyms used in all searches** (Flora of Greece, Euro+Med): {', '.join(nm['search_names'][1:]) or '—'}
- **Additional GBIF synonyms** (database and full-text searches only; may include misapplied names): {', '.join(n for n in nm.get('extended_names', [])[1:] if n not in nm['search_names']) or '—'}
- **Greek floristic regions (Dimopoulos et al. 2013, 2016):** {regions}

{START}
{synthesis}
{END}

## Specimens and observations

{len(recs)} records; {len(prim)} after removing duplicates; {sum(1 for r in prim if has_xy(r))} unique records with coordinates.

{_md_table(src_rows, ["source", "records", "with coordinates", "generalised/withheld"])}
Herbaria / institutions (unique records): {', '.join(f'{k} {v}' for k, v in inst.most_common(20)) or '—'}

### Candidate sites ({len(sites)})

Clusters (1 km) of unique records with precise coordinates (uncertainty ≤ 5 km, not generalised), newest first.
Also in `candidate_sites.csv`, the GeoPackage, the KML and the GPX.

{_md_table(sites, ["site_id", "latitude", "longitude", "n_records", "sources", "last_year", "best_uncertainty_m", "example_locality"], 60)}
### Candidate areas ({len(areas)})

10 km clusters of all unique records with coordinates, including generalised ones (DiSSCo Hellas 10 km grid, obscured iNaturalist).
These are areas where the species is known but no precise site is published: confirm them in the field or ask the curators or observers.

{_md_table(areas, ["site_id", "latitude", "longitude", "n_records", "n_generalised", "sources", "last_year", "example_locality"], 60)}
### Records without precise coordinates

{sum(1 for r in prim if not has_xy(r))} unique records have no coordinates and {sum(1 for r in prim if r.get('coords_generalised') == 'yes')} have generalised ones.
Their locality text is in `occurrences.csv`; georeference the ones that matter (SKILL.md, step 4).

## Natura 2000 sites listing the species ({len(n2k)})

{_md_table(n2k, ["site_code", "site_name", "population_rating", "pop_min", "pop_max", "unit", "data_quality", "sdf_url"])}
Article 17 (2019–2024) distribution: {'see layer `art17_distribution` in the GeoPackage' if (d / 'art17_grid.geojson').exists() else 'not available (species not in the Habitats Directive annexes, or sensitive)'}.

## Localities extracted from literature and floras ({len(lit)})

{_md_table(lit, ["locality", "latitude", "longitude", "uncertainty_m", "source_ref", "page", "year"])}
## Literature leads ({len(leads)})

By type: {', '.join(f'{k} {v}' for k, v in kinds.most_common()) or '—'}

### Theses

{_md_table(thesis, ["source", "kind", "year", "title", "institution", "url"], 80)}
### Other literature

{_md_table(other, ["source", "kind", "year", "title", "url"], 80)}
Full list: `leads.csv`. Flora text hits: `text_hits.md`.

## Manual follow-ups

- **Precise coordinates withheld:** {', '.join(f'{k} ({v})' for k, v in w_inst.items()) or 'none'}. Email the curators: NHMC (Natural History Museum of Crete), ATHU (Univ. Athens), TAU (AUTH), ATH (Goulandris Museum), MAICH, UPA (Patras).
- PhD theses from didaktorika.gr: the PDFs sit behind a CAPTCHA, so download them by hand.
- Print-only floras not configured as local PDFs: Strid, *Atlas of the Aegean Flora* (2016); Strid & Tan, *Mountain Flora of Greece*; Strid & Tan, *Flora Hellenica*; Turland et al., *Flora of the Cretan Area* (1993).
- NECCA (necca.gov.gr) monitoring data and EVA vegetation plots: available on request.
- Collecting permits: protected species (P.D. 67/1981, Habitats Directive annexes) and protected areas need a permit from the Ministry of Environment / NECCA.

## Source log

{_md_table(problems, ["source", "status", "detail"]) if problems else 'All sources answered.'}
"""
    rp.write_text(md, encoding="utf-8")
